def splitArraySameAverage(nums: list[int]) -> bool:
    n = len(nums)
    if n <= 1: return False
    total = sum(nums)
    mid = n // 2
    left, right = nums[:mid], nums[mid:]
    left_sums = [set() for _ in range(len(left) + 1)]
    left_sums[0].add(0)
    for x in left:
        for sz in range(len(left_sums) - 1, 0, -1):
            for s in left_sums[sz - 1]:
                left_sums[sz].add(s + x)
    right_sums = [set() for _ in range(len(right) + 1)]
    right_sums[0].add(0)
    for x in right:
        for sz in range(len(right_sums) - 1, 0, -1):
            for s in right_sums[sz - 1]:
                right_sums[sz].add(s + x)
    for k in range(1, mid + 1):
        if (total * k) % n == 0:
            target = (total * k) // n
            for l_sz in range(min(k, len(left)) + 1):
                r_sz = k - l_sz
                if r_sz <= len(right):
                    for s1 in left_sums[l_sz]:
                        if (target - s1) in right_sums[r_sz]:
                            return True
    return False

